std::string configured(const std::string& source,int enabled){require(enabled==0||enabled==1,"enabled must be0 or1");require(source.find(configBegin)==std::string::npos&&source.find(configEnd)==std::string::npos,"existing native-Sun configuration");return angular::replaceOne(source,tracer::includeBegin,tracer::includeBegin+configBegin+"#define NATIVE_SUN_ENABLED "+std::to_string(enabled)+"\n"+configEnd);}
