std::string observed(const std::string& source){auto result=angular::replaceOne(angular::observed(source),"    gl_FragData[1]=vec4(n,OBS_residualGrazing);\n","    gl_FragData[1]=vec4(n,WNS_status.x);\n");result=angular::replaceOne(result,"    gl_FragData[7]=vec4(scatter,float(residualEligible));\n","    gl_FragData[7]=vec4(scatter,WNS_status.y);\n");require(tracer::recoveredObserver(result)==source,"native requested/applied STORE must recover exact main");return result;}
